// Curated contacts, never generated by AI or extracted from submitted content.
// Sources and review procedure: frontend/docs/recovery-help.md.
export const CONTACTS_REVIEWED = '2026-11-25';
export const SITUATIONS = ['clicked', 'shared', 'paid', 'downloaded', 'threatened', 'danger', 'unsure'];
export const PROVIDERS = ['unknown', 'gcash', 'maya', 'bank', 'account'];
export const CONTACTS = {
  emergency: { name: 'Emergency 911', phone: '911', tel: '911', note: 'emergency', url: 'https://ehotlines.e.gov.ph/', source: 'https://ehotlines.e.gov.ph/' },
  gcash: { name: 'GCash', phone: '2882', tel: '2882', note: 'gcash', url: 'https://help.gcash.com/hc/en-us/p/contact-us?chatbot-open=yes', source: 'https://help.gcash.com/hc/en-us/p/contact-us?chatbot-open=yes' },
  maya: { name: 'Maya', phone: '(02) 8845 7788', tel: '+63288457788', note: 'maya', url: 'https://www.maya.ph/contact-us', source: 'https://www.maya.ph/contact-us' },
  bank: { name: 'recovery.bankName', note: 'bank', url: 'https://www.bsp.gov.ph/SitePages/FinancialStability/BSPVerifier.aspx', source: 'https://www.bsp.gov.ph/SitePages/FinancialStability/BSPVerifier.aspx' },
  cicc: { name: 'CICC', phone: '1326', tel: '1326', note: 'cicc', url: 'https://cicc.gov.ph/', source: 'https://cicc.gov.ph/wp-content/uploads/2025/04/KONTRA-SCAM-Brochure.pdf' },
};

export function toggleSituation(selected, id) {
  if (!SITUATIONS.includes(id)) return selected;
  if (selected.includes(id)) return selected.filter(item => item !== id);
  return id === 'unsure' ? ['unsure'] : [...selected.filter(item => item !== 'unsure'), id];
}

export function buildRecoveryPlan({ situations = [], provider = 'unknown', country = 'PH' } = {}) {
  const selected = new Set(situations.filter(id => SITUATIONS.includes(id)));
  if (!selected.size) return { steps: [], contacts: [] };
  const steps = [];
  if (selected.has('danger')) steps.push('safety');
  if (selected.has('paid')) steps.push('payment');
  if (selected.has('shared')) steps.push('account');
  if (selected.has('downloaded')) steps.push('device');
  steps.push('stop');
  if (selected.has('unsure')) steps.push('review');
  if (selected.has('paid') || selected.has('threatened') || selected.has('danger') || selected.has('shared')) steps.push('evidence');
  if (selected.has('threatened')) steps.push('threat');
  if (selected.has('paid') || selected.has('shared') || selected.has('downloaded') || selected.has('threatened') || selected.has('danger')) steps.push('report');
  const contacts = [];
  if (country === 'PH') {
    if (selected.has('danger')) contacts.push('emergency');
    const financial = selected.has('paid') || selected.has('shared') && ['gcash', 'maya', 'bank'].includes(provider);
    if (financial) contacts.push(['gcash', 'maya'].includes(provider) ? provider : 'bank');
    if (selected.has('paid') || selected.has('shared') || selected.has('downloaded') || selected.has('threatened') || selected.has('danger') || selected.has('unsure')) contacts.push('cicc');
  }
  return { steps, contacts };
}

export function recoverySummary({ situations, provider, providerName, country, countryName, completed, plan, t, date = new Date() }) {
  return [
    t('recovery.label'), t('recovery.planTitle'), date.toISOString(),
    `${t('recovery.country')}: ${country === 'PH' ? t('recovery.ph') : countryName || t('recovery.otherCountry')}`,
    ...situations.filter(id => SITUATIONS.includes(id)).map(id => `- ${t(`recovery.situation.${id}`)}`),
    `${t('recovery.provider')}: ${providerName || t(`recovery.provider.${PROVIDERS.includes(provider) ? provider : 'unknown'}`)}`,
    '', t('recovery.steps'),
    ...plan.steps.map(id => `${completed.includes(id) ? '[x]' : '[ ]'} ${t(`recovery.step.${id}.title`)}: ${t(`recovery.step.${id}.body`)}`),
    '', t('recovery.contacts'),
    ...plan.contacts.map(id => `${id === 'bank' ? t(CONTACTS[id].name) : CONTACTS[id].name}: ${CONTACTS[id].phone || ''} ${CONTACTS[id].url}`),
    '', t('recovery.limit'), `${t('recovery.reviewed')}: ${CONTACTS_REVIEWED}`,
  ].join('\n');
}
